import{getWrapper as e}from"fetch";export async function getFriendRequestToast(){return e({url:"/friend/getFriendRequestToast",$loadingDiv:null,loading:"",dataHandler:e=>{let t=document.createElement("div");t.innerHTML=e,document.getElementById("toastsDiv").appendChild(t);let n=document.getElementById("friendRequestToast");if(n){new bootstrap.Toast(n).show()}}})}export function createToast(e,t="primary",n="bi-info-circle",o=5e3){let a=document.querySelector(".toast-container");a||(a=document.createElement("div"),a.className="toast-container position-fixed bottom-0 end-0 p-3",document.body.appendChild(a));const i="toast-"+Date.now(),s=`\n        <div id="${i}" class="toast align-items-center text-bg-${t} border-0" role="alert" aria-live="assertive" aria-atomic="true">\n            <div class="d-flex">\n                <div class="toast-body">\n                    <i class="bi ${n} me-2"></i>${e}\n                </div>\n                <button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast" aria-label="Close"></button>\n            </div>\n        </div>\n    `;a.insertAdjacentHTML("beforeend",s);const d=document.getElementById(i),r=new bootstrap.Toast(d,{autohide:!0,delay:o});return r.show(),d.addEventListener("hidden.bs.toast",()=>{d.remove()}),r}